#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

using namespace std;
bool fill(string* allrows, char dir, int x, int y, int fl, bool isfl, bool fill){
    if (dir != '0' && dir == '.'){
        if (isfl && !(y >= fl)){
            return 0;
        }
        if (fill){
            allrows[y].at(x) = '~';
        }
        return 1;
    }
    else{
        return 0;
    }
}
bool cond(int stream, int dis, int cond){
    if (stream + dis != cond){
        return 1;
    }
    else{
        return 0;
    }
}
void stream(string* allrows, int streamx, int streamy, int fl, int sizey, int sizex){
    char below;
    char left;
    char right;
    char leftdown;
    char rightdown;
    char above;
    if (cond(streamy, 1, sizey)){
       below = allrows[streamy + 1].at(streamx);
    }
    else{
        below = '0';
    }
    if (cond(streamy, -1, -1)){
        above = allrows[streamy - 1].at(streamx);
    }
    else{
        above = '0';
    }
    if (cond(streamx, -1, -1)){
        left = allrows[streamy].at(streamx - 1);
    }
    else{
        left = '0';
    }
    if (cond(streamx, 1, sizex)){
        right = allrows[streamy].at(streamx + 1);
    }
    else{
        right = '0';
    }
    if (below != '0'){
        if (left != '0'){
            leftdown = allrows[streamy + 1].at(streamx - 1);
        }
        if (right != '0'){
            rightdown = allrows[streamy + 1].at(streamx + 1);
        }
    }
    if (streamy >= fl){
        if (fill(allrows, left, streamx - 1, streamy, fl, 1, 1)){
            stream(allrows, streamx - 1, streamy, fl, sizey, sizex);
        }
        if (fill(allrows, right, streamx + 1, streamy, fl, 1, 1)){
            stream(allrows, streamx + 1, streamy, fl, sizey, sizex);
        }
        if (fill(allrows, above, streamx, streamy - 1, fl, 1, 1)){
            stream(allrows, streamx, streamy - 1, fl, sizey, sizex);
        }
        if (fill(allrows, below, streamx, streamy + 1, fl, 1, 1)){
            stream(allrows, streamx, streamy + 1, fl, sizey, sizex);
        }
    }
    else{
        switch (below){
            case '_':
            {
                if (fill(allrows, left, streamx - 1, streamy, fl, 0, 1)){
                    stream(allrows, streamx - 1, streamy, fl, sizey, sizex);
                }
                if (fill(allrows, right, streamx + 1, streamy, fl, 0, 1)){
                    stream(allrows, streamx + 1, streamy, fl, sizey, sizex);
                }
                break;
            }
            case '^':
            {
                if (fill(allrows, left, streamx - 1, streamy, fl, 0, 0)){
                    if (fill(allrows, leftdown, streamx - 1, streamy + 1, fl, 0, 1)){
                        stream(allrows, streamx - 1, streamy + 1, fl, sizey, sizex);
                    }
                }
                if (fill(allrows, right, streamx + 1, streamy, fl, 0, 0)){
                    if (fill(allrows, rightdown, streamx + 1, streamy + 1, fl, 0, 1)){
                        stream(allrows, streamx + 1, streamy + 1, fl, sizey, sizex);
                    }
                }
                break;
            }
            case '|':
            {
                bool wl = 0;
                if (allrows[streamy].at(streamx) != '!'){
                    if (fill(allrows, left, streamx - 1, streamy, fl, 0, 0)){
                        if (fill(allrows, leftdown, streamx - 1, streamy + 1, fl, 0, 1)){
                            stream(allrows, streamx - 1, streamy + 1, fl, sizey, sizex);
                        }
                        else{
                            wl = 1;
                        }
                    }
                    else{
                        wl = 1;
                    }
                    if (fill(allrows, right, streamx + 1, streamy, fl, 0, 0)){
                        if (fill(allrows, rightdown, streamx + 1, streamy + 1, fl, 0, 1)){
                            stream(allrows, streamx + 1, streamy + 1, fl, sizey, sizex);
                        }
                        else{
                            wl = 1;
                        }
                    }
                    else{
                        wl = 1;
                    }
                    if (wl){
                        allrows[streamy + 1].at(streamx) = '!';
                        stream(allrows, streamx, streamy + 1, fl, sizey, sizex);
                    }
                }
                else{
                    if (streamy + 1 < fl){
                        allrows[streamy + 1].at(streamx) = '!';
                    }
                    stream(allrows, streamx, streamy + 1, fl, sizey, sizex);
                }
                break;
            }
            case '/':
            {
                if (fill(allrows, leftdown, streamx - 1, streamy + 1, fl, 0, 1)){
                    stream(allrows, streamx - 1, streamy + 1, fl, sizey, sizex);
                }
                break;
            }
            case '\\':
            {
                if (fill(allrows, rightdown, streamx + 1, streamy + 1, fl, 0, 1)){
                    stream(allrows, streamx + 1, streamy + 1, fl, sizey, sizex);
                }
                break;
            }
            case '.':
            {
                fill(allrows, below, streamx, streamy + 1, fl, 0, 1);
                stream(allrows, streamx, streamy + 1, fl, sizey, sizex);
                break;
            }
            default:
            {
                break;
            }
        }
    }
}
int main()
{
    int w; int h; int r;
    cin >> w; cin.ignore();
    cin >> h; cin.ignore();
    cin >> r; cin.ignore();
    string allrows[h];
    for (int i = 0; i < h; i++) {
        getline(cin, allrows[i]);
    }
    for (int i = 0; i < h; ++i){
        for (int e = 0; e < w; ++e){
            if (allrows[i].at(e) == 'o'){
                stream(allrows, e, i, r, h, w);
            }
        }
    }

    for (int i = 0; i < h; ++i){
        cout << allrows[i] << endl;
    }
}

data.statement:
Here at Water-Generating Cells™ Corporation, we sell <<cells that generate water>> to our clients and fill whatever holes they have so they can make lakes, pools, miniature waterfalls, things of the type, with ease. We are trying to offer an experience where the client can see what their body of water would look like before we deliver and apply the cells. That's where you come in.

You're going to have to make a program that takes in the [[w]]idth and [[h]]eight of the client's area, then a <<2-dimensional ASCII representation of it.>> In the area, there is going to be <<at least one water-generating cell>> {{o}}. It generates a water stream {{~}} (it's a tilde, you might not be able to see it) that initally only goes downwards, but will <<stop and start flooding at a certain>> [[r]]<<ow>> (0-based).

You also need to take into consideration these characters:

{{.}} is an empty space;

{{_}} is a flat terrain. When a stream that is falling downward encounters it, the stream splits into two and <<stays in the row above the terrain>> before continuing to descend. Any of the two halves may cease to exist if obstructed initially;

{{^}} is a sharp terrain. When a downward stream encounters it, it splits into two, <<but on the row of the terrain.>>

{{|}} is a thin wall. It works like sharp terrain, but <<when any of the two streams are initially blocked>>, it becomes waterlogged ({{!}}) and may work like a downwards stream, only waterlogging thin walls beneath it. Once there are no more thin walls, it behaves like a normal water stream. Thin wall is not waterlogged when in flood water;

{{#}} is a thick wall. <<Streams do not split upon contact with it>>;

{{\}} and {{/}} are slopes. <<Streams fall diagonally>> upon contact with the slopes (the stream goes to the side of the slope);

In the case of a stream encountering another {{o}} water-generating cell, it ceases to exist because it is not necessary, as the cell generates another stream anyway.

In any case of a stream (half) being obstructed by terrain or another cell initially after splitting or moving, it ceases to exist. In the case of sharp splitting terrain ({{|}}, {{^}}), the spaces to the left and right of the terrain, and the spaces above those, must be unobstructed in order for the stream to split.

The terrain cannot be permeated, with the exception of thin wall {{|}}, but only when it is waterlogged.

If there is terrain below a cell, the cell still behaves like a falling water stream, so if for example there is a cell over a {{_}} flat terrain, it will split to form {{~}} water at its sides, but the cell is not changed.

After applying the changes to the ASCII grid, output the result.

data.constraints:
{{0}} <= [[w]] <= {{30}}
{{0}} <= [[h]] <= {{30}}
{{0}} <= [[r]] <= [[h]] - {{1}}
There is going to be <<at least one water-generating cell>> {{o}} in the grid.
